<?php

declare(strict_types=1);
require __DIR__.'/notes.php';
// Reaproveita apenas fixtures descartáveis da suíte-base; nenhuma conta local.
$pdo->prepare("INSERT INTO project_members(tenant_id,project_id,user_id,role) VALUES (?,?,?,'member')")->execute([$tenant,$projectId,$member]);
$edit=$notes->create($owner,'Antes da edição',$projectId);$notes->update($owner,$edit,"Texto editado\n<script>window.editXss=true</script>");
check($notes->page($owner,$projectId)['items'][0]['body']==="Texto editado\n<script>window.editXss=true</script>",'Editar texto integral');
noteError(404,fn()=>$notes->update($member,$edit,'Alheia'),'Só autor edita nota');noteError(422,fn()=>$notes->update($owner,$edit,str_repeat('x',5001)),'Limite na edição');
$csrf=boardLogin($users['owner']['email']);check(noteRequest('/notes/'.$edit.'/update',['body'=>'Sem token'])[0]===419,'CSRF edição');check(noteRequest('/notes/'.$edit.'/update',['_token'=>$csrf,'body'=>'Texto HTTP','project_id'=>$foreign,'user_id'=>$outside])[0]===200,'Edição usa identidade e destino originais');
