function reviseChange(int $actor,string $action,array $payload):array{global $boards,$projectId;$fresh=$boards->state($actor,$projectId);return $boards->mutate($actor,$projectId,$fresh['version'],$action,$payload);}
reviseChange($owner,'task.update',['task_id'=>$task,'title'=>'Excluir somente pelo autor','description'=>'Texto HTTP','priority'=>'normal','due_on'=>'','assignee_ids'=>[$owner,$member]]);
reviseChange($owner,'checklist.create',['task_id'=>$task,'title'=>'Lista a remover']);$list=(int)$pdo->query('SELECT id FROM task_checklists WHERE task_id='.$task)->fetchColumn();reviseChange($owner,'item.create',['task_id'=>$task,'checklist_id'=>$list,'title'=>'Item dependente']);
reviseChange($member,'comment.create',['task_id'=>$task,'body'=>'Comentário de outro participante']);(new App\Services\NotificationWorker($pdo))->run(new DateTimeImmutable('+1 second'),500);reviseChange($owner,'comment.create',['task_id'=>$task,'body'=>'Aviso pendente']);
check($boards->task($owner,$projectId,$task)['details']['can_delete']===true,'Criador recebe ação');check($boards->task($member,$projectId,$task)['details']['can_delete']===false,'Outro participante não recebe ação');
noteError(403,fn()=>reviseChange($member,'task.delete',['task_id'=>$task,'confirm'=>true,'created_by'=>$member]),'Não pode forjar criador');noteError(422,fn()=>reviseChange($owner,'task.delete',['task_id'=>$task]),'Confirmação explícita');
$version=$boards->state($owner,$projectId)['version'];$outbox=(int)$pdo->query('SELECT COUNT(*) FROM notification_outbox WHERE task_id='.$task)->fetchColumn();check($outbox>0,'Fixture com notificações');
$pdo->exec("CREATE TRIGGER reject_task_delete BEFORE INSERT ON activity_logs FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='rollback delete'");
try{try{reviseChange($owner,'task.delete',['task_id'=>$task,'confirm'=>true]);check(false,'Falha de auditoria esperada');}catch(PDOException){}check((int)$pdo->query('SELECT COUNT(*) FROM tasks WHERE id='.$task)->fetchColumn()===1,'Rollback preserva tarefa');check((int)$pdo->query('SELECT COUNT(*) FROM task_comments WHERE task_id='.$task)->fetchColumn()===2,'Rollback preserva comentários');check((int)$pdo->query('SELECT COUNT(*) FROM notification_outbox WHERE task_id='.$task)->fetchColumn()===$outbox,'Rollback preserva outbox');check($boards->state($owner,$projectId)['version']===$version,'Rollback não avança versão');}finally{$pdo->exec('DROP TRIGGER reject_task_delete');}
$csrf=boardLogin($users['owner']['email']);$fresh=$boards->state($owner,$projectId);check(boardRequest($projectId,['action'=>'task.delete','version'=>$fresh['version'],'task_id'=>$task,'confirm'=>true])[0]===419,'CSRF exclusão da tarefa');
check(boardRequest($projectId,['_token'=>$csrf,'action'=>'task.delete','version'=>$fresh['version'],'task_id'=>$task,'confirm'=>true])[0]===200,'Exclusão HTTP do criador');
foreach(['tasks'=>'id','task_comments'=>'task_id','task_checklists'=>'task_id','task_checklist_items'=>'task_id','task_assignees'=>'task_id'] as $table=>$field)check((int)$pdo->query('SELECT COUNT(*) FROM '.$table.' WHERE '.$field.'='.$task)->fetchColumn()===0,'Remoção dependente '.$table);
check((int)$pdo->query('SELECT COUNT(*) FROM activity_logs WHERE project_id='.$projectId." AND action='task.deleted'")->fetchColumn()===1,'Auditoria da exclusão preservada');check((int)$pdo->query('SELECT COUNT(*) FROM notification_outbox WHERE task_id='.$task)->fetchColumn()===0,'Sem links de notificação para tarefa excluída');
check(request('/projects/'.$projectId.'/tasks/'.$task)[0]===404,'Detalhe excluído indisponível');noteError(404,fn()=>reviseChange($owner,'task.delete',['task_id'=>$task,'confirm'=>true]),'Exclusão repetida sem duplicar');
// Ser dono/admin do projeto não permite excluir uma tarefa criada por outro participante.
$memberNote=$notes->create($member,'Criada pelo participante',null);$memberTask=$notes->convert($member,$memberNote,$projectId,$column);noteError(403,fn()=>reviseChange($owner,'task.delete',['task_id'=>$memberTask,'confirm'=>true]),'Proprietário não exclui tarefa alheia');
$pdo->prepare("UPDATE project_members SET role='viewer' WHERE tenant_id=? AND project_id=? AND user_id=?")->execute([$tenant,$projectId,$member]);check($boards->task($member,$projectId,$memberTask)['details']['can_delete']===true,'Autor continua podendo excluir após virar visualizador');reviseChange($member,'task.delete',['task_id'=>$memberTask,'confirm'=>true]);
$race=$notes->convert($owner,$notes->create($owner,'Excluir uma única vez',null),$projectId,$column);$version=$boards->state($owner,$projectId)['version'];$jobs=[];for($i=0;$i<2;$i++)$jobs[]=proc_open([PHP_BINARY,__DIR__.'/task-delete-child.php',(string)$owner,(string)$projectId,(string)$version,(string)$race],[STDIN,STDOUT,STDERR],$pipes,dirname(__DIR__));foreach($jobs as $job)check(is_resource($job)&&proc_close($job)===0,'Exclusões concorrentes');
$remaining=$pdo->query("SELECT position FROM tasks WHERE project_id={$projectId} AND column_id={$column} ORDER BY position")->fetchAll(PDO::FETCH_COLUMN);check(array_map('intval',$remaining)===($remaining?range(0,count($remaining)-1):[]),'Posições recompostas');
$blocked=$notes->convert($owner,$notes->create($owner,'Sem acesso',null),$projectId,$column);$pdo->prepare('DELETE FROM project_members WHERE tenant_id=? AND project_id=? AND user_id=?')->execute([$tenant,$projectId,$member]);noteError(404,fn()=>reviseChange($member,'task.delete',['task_id'=>$blocked,'confirm'=>true]),'Acesso revogado');
echo "OK: edição privada de notas, conversão editada, exclusão exclusiva do criador, dependências, auditoria, notificações, CSRF, rollback e concorrência.\n";
